import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { validateChannel } from '../../scripts/desktop-release.mjs';
const read = path => readFileSync(path, 'utf8');
const config = JSON.parse(read('src-tauri/tauri.conf.json'));
assert.match(config.version, /^\d+\.\d+\.\d+$/, 'Desktop must use an independent literal SemVer');
assert.equal(read('src-tauri/Cargo.toml').match(/^version = "([^"]+)"/m)?.[1], config.version);
assert.equal(read('src-tauri/Cargo.lock').match(/name = "casesim-desktop"\s+version = "([^"]+)"/)?.[1], config.version);
assert.equal(config.build.frontendDist, '../desktop');
assert.equal(config.build.devUrl, undefined);
assert.deepEqual(config.app.windows, []);
assert.equal(config.app.withGlobalTauri, false);
assert.deepEqual(config.app.security.capabilities, ['recovery', 'desktop']);
const capability = JSON.parse(read('src-tauri/capabilities/recovery.json'));
assert.equal(capability.local, true);
assert.equal(capability.remote, undefined);
assert.deepEqual(capability.permissions, ['allow-connect']);
assert.deepEqual(capability.windows, ['main']);
const controls = JSON.parse(read('src-tauri/capabilities/desktop.json'));
assert.equal(controls.local, true);
assert.equal(controls.remote, undefined);
assert.deepEqual(controls.windows, ['desktop']);
assert.deepEqual(controls.permissions, ['allow-desktop-action', 'allow-desktop-status', 'allow-check-update', 'allow-download-update', 'allow-install-update']);
assert.equal(config.plugins.updater.requireSignedVersion, true);
assert.equal(config.plugins.updater.allowDowngrades, undefined);
for (const flag of ['dangerousInsecureTransportProtocol', 'dangerousAcceptInvalidCerts', 'dangerousAcceptInvalidHostnames']) assert.notEqual(config.plugins.updater[flag], true);
assert.deepEqual(config.plugins.updater.endpoints, []);
assert.equal(config.plugins.updater.pubkey, '');
const notes = JSON.parse(read('desktop/release-notes.json'));
assert.equal(notes[0].version, config.version);
assert.equal(new Set(notes.map(n => n.version)).size, notes.length);
validateChannel(JSON.parse(read('src-tauri/update-channel.json')));
assert.deepEqual(config.bundle.targets, ['nsis']);
assert.equal(config.bundle.windows.webviewInstallMode.type, 'embedBootstrapper');
console.log(`Independent desktop configuration valid: ${config.version}`);

const pkg = JSON.parse(read('package.json'));
const lock = JSON.parse(read('package-lock.json'));
assert.equal(pkg.version, config.version);
assert.equal(lock.version, config.version);
assert.equal(lock.packages[''].version, config.version);
assert.deepEqual(Object.keys(pkg.devDependencies).sort(), ['@playwright/test', '@tauri-apps/cli']);
assert.equal(pkg.dependencies, undefined);
